import { Asset } from 'expo-asset'
import { Directory, File, Paths } from 'expo-file-system'
import type { SandTable } from './tableSize'
// @ts-ignore - generated by scripts/gen-sand.mjs (plain JS)
import { FILES, KEY, PAGE, TEXTS } from '../../assets/sand'

/** The cache folder with the sand page and the table's clears, made once per
 * engine (KEY), as a uri ending in '/'. The phones' WebView loads the page from
 * it (SandView.tsx); desktop's iframe reads the clears there (SandView.web.tsx,
 * served as app://cache/…). */
export async function prepareSand(table: SandTable): Promise<string> {
  const dir = new Directory(Paths.cache, `sand-${KEY}`)
  if (!dir.exists) dir.create({ intermediates: true })
  for (const name of Object.keys(FILES as Record<string, number>).filter((n) => n.startsWith(`${table}-`))) {
    const dest = new File(dir, name)
    if (dest.exists) continue
    const asset = Asset.fromModule((FILES as Record<string, number>)[name])
    await asset.downloadAsync()
    await new File(asset.localUri ?? asset.uri).copy(dest)
  }
  // The clear patterns ship as text (see scripts/gen-sand.mjs): written, not copied.
  for (const [name, text] of Object.entries(TEXTS as Record<string, string>).filter(([n]) => n.startsWith(`${table}-`))) {
    const dest = new File(dir, name)
    if (!dest.exists) dest.writeSync(text)
  }
  const page = new File(dir, 'index.html')
  if (!page.exists) page.writeSync(PAGE as string)
  return dir.uri.endsWith('/') ? dir.uri : `${dir.uri}/`
}
